import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  images: {
    domains: ['images.squarespace-cdn.com'],
  },
  // Storefront Studio example sites are static pages in public/examples,
  // generated by the storefront-demos builder (EXAMPLE_BASE=/examples).
  async rewrites() {
    return [
      { source: '/examples', destination: '/examples/index.html' },
      { source: '/examples/:type(home-services|auto|salon)', destination: '/examples/:type/index.html' },
    ];
  },
};

export default nextConfig;
